def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
        return False
    data = responseBody.get("data") or {}
    members = data.get("members")
    if not isinstance(members, list):
        return False
    ok = statusCode == 200 and responseBody.get("code") == 0 and bool(responseBody.get("requestId"))
    ok = ok and data.get("id") == globalParam.get("r") and globalParam.get("r2") == globalParam.get("r")
    ok = ok and len(members) == 3 and set(members) == {globalParam.get("a_id"), globalParam.get("b_id"), globalParam.get("c_id")}
    return ok

def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
        return False
    data = responseBody.get("data") or {}
    items = data.get("items")
    if not isinstance(items, list):
        return False
    matching = [room for room in items if room.get("topicId") == globalParam.get("t")]
    ok = statusCode == 200 and responseBody.get("code") == 0 and bool(responseBody.get("requestId"))
    return ok and len(matching) == 1 and matching[0].get("id") == globalParam.get("r")
